import React, { useEffect, useState } from 'react';
import api from '../utils/api';

const ChartComponent = () => {
    const [data, setData] = useState(null);
    const [error, setError] = useState(null);
    const [aircrafts, setAircrafts] = useState([]);
    const [selectedAircraft, setSelectedAircraft] = useState('All');
    const [years, setYears] = useState([]);
    const [selectedYear, setSelectedYear] = useState('All');
    const [months, setMonths] = useState(['All', 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']);
    const [selectedMonth, setSelectedMonth] = useState('All');
    const [revenuePerHour, setRevenuePerHour] = useState({}); // Add state for revenue per hour

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                console.log('Fetched Data:', result.data);
                setData(result.data);

                // Extract unique aircrafts and years directly from the invoices data
                const invoices = result.data.invoices || [];
                const uniqueAircrafts = Array.from(new Set(invoices.map(invoice => invoice.Aircraft)));
                setAircrafts(['All', ...uniqueAircrafts]);

                const uniqueYears = Array.from(new Set(invoices.map(invoice => {
                    const dateParts = invoice['Trip start Z'].split('/');
                    return parseInt(dateParts[2], 10);
                })));
                setYears(['All', ...uniqueYears.sort((a, b) => a - b)]);

            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        if (!data) return;

        const { invoices, loggedFlights } = data;

        // Filter invoices with status "Invoiced"
        let filteredInvoices = invoices.filter(invoice => invoice.Status === 'Invoiced');

        if (selectedAircraft !== 'All') {
            filteredInvoices = filteredInvoices.filter(invoice => invoice.Aircraft === selectedAircraft);
        }

        if (selectedYear !== 'All') {
            filteredInvoices = filteredInvoices.filter(invoice => {
                const dateParts = invoice['Trip start Z'].split('/');
                return parseInt(dateParts[2], 10) === parseInt(selectedYear);
            });
        }

        if (selectedMonth !== 'All') {
            const monthIndex = months.indexOf(selectedMonth);
            filteredInvoices = filteredInvoices.filter(invoice => {
                const dateParts = invoice['Trip start Z'].split('/');
                return parseInt(dateParts[0], 10) === monthIndex;
            });
        }

        const revenuePerHour = {};

        filteredInvoices.forEach(invoice => {
            const trip = invoice.Trip;
            const aircraft = invoice.Aircraft;
            const price = parseFloat(invoice.Price);

            // Get the flights matching the trip and aircraft
            const flights = loggedFlights.filter(flight => flight.Trip === trip && flight.Aircraft === aircraft);
            const totalFlightHours = flights.reduce((sum, flight) => sum + parseFloat(flight['Flight hrs']), 0);

            if (!revenuePerHour[aircraft]) {
                revenuePerHour[aircraft] = { totalPrice: 0, totalFlightHours: 0 };
            }

            revenuePerHour[aircraft].totalPrice += price;
            revenuePerHour[aircraft].totalFlightHours += totalFlightHours;
        });

        console.log('Revenue per Hour:', revenuePerHour);
        setRevenuePerHour(revenuePerHour); // Set the calculated revenue per hour
    }, [data, selectedAircraft, selectedYear, selectedMonth]);

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div>
            <h1>Revenue per Hour of Aircrafts</h1>
            <div>
                <label>
                    Aircraft:
                    <select value={selectedAircraft} onChange={e => setSelectedAircraft(e.target.value)}>
                        {aircrafts.map(aircraft => (
                            <option key={aircraft} value={aircraft}>{aircraft}</option>
                        ))}
                    </select>
                </label>
                <label>
                    Year:
                    <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)}>
                        {years.map(year => (
                            <option key={year} value={year}>{year}</option>
                        ))}
                    </select>
                </label>
                <label>
                    Month:
                    <select value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                        {months.map((month, index) => (
                            <option key={index} value={month}>{month}</option>
                        ))}
                    </select>
                </label>
            </div>
            <div>
                {Object.keys(revenuePerHour).map(aircraft => (
                    <div key={aircraft}>
                        <p>{aircraft}: {(revenuePerHour[aircraft].totalPrice / revenuePerHour[aircraft].totalFlightHours).toFixed(2)}</p>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default ChartComponent;
